import SwiftUI
import Montage

struct ContentBadgePreview: View {
    @State private var isSolid: Bool = true
    @State private var sizeIndex: Int = 0
    @State private var colorStyleIndex: Int = 0
    @State private var leadingIcon: Bool = false
    @State private var leadingIconUsesTemplate: Bool = true
    @State private var trailingIcon: Bool = false
    @State private var trailingIconUsesTemplate: Bool = true
    @State private var foregroundColor: SwiftUI.Color = .semantic(.foregroundNeutralTertiary)
    @State private var backgroundColor: SwiftUI.Color = .semantic(.surfaceAccentVioletOpaque)
    
    private let sizes: [ContentBadge.Size] = [
        .xsmall,
        .small,
        .medium
    ]
    
    var body: some View {
        PreviewLayout {
            ContentBadge(
                variant: isSolid ? .solid : .outlined,
                text: "Badge"
            )
            .size(sizes[sizeIndex])
            .colorStyle(
                colorStyleIndex == 0 ? .neutral(foregroundColor) : .accent(foregroundColor, background: backgroundColor)
            )
            .modifying { original in
                var mutated = original
                if leadingIcon {
                    mutated = mutated.leadingIcon(.agentColor, usesTemplate: leadingIconUsesTemplate)
                }
                if trailingIcon {
                    mutated = mutated.trailingIcon(.agentColor, usesTemplate: trailingIconUsesTemplate)
                }
                return mutated
            }
        } options: {
            ToggleOptionRow("solid", isOn: $isSolid)
            SegmentedIndexRow("size", index: $sizeIndex, labels: sizes.map(\.description))
            SegmentedIndexRow("colorStyle", index: $colorStyleIndex, labels: colorStyles.map(\.description))
            if colorStyleIndex == 1 {
                MenuOptionRow("accent token", menuLabel: "select") {
                    ForEach(AccentPreset.allCases, id: \.self) { preset in
                        Button(preset.title) { apply(preset) }
                    }
                }
            }
            ColorPickerOptionRow("contentColor", selection: $foregroundColor)
            if colorStyleIndex == 1 {
                ColorPickerOptionRow("backgroundColor", selection: $backgroundColor)
            }
            HStack {
                ToggleOption("leadingIcon", isOn: $leadingIcon)
                if leadingIcon {
                    ToggleOption("usesTemplate", isOn: $leadingIconUsesTemplate)
                }
            }
            HStack {
                ToggleOption("trailingIcon", isOn: $trailingIcon)
                if trailingIcon {
                    ToggleOption("usesTemplate", isOn: $trailingIconUsesTemplate)
                }
            }
        }
        .onChange(of: colorStyleIndex) { newValue in
            if newValue == 0 {
                foregroundColor = .semantic(.foregroundNeutralTertiary)
            } else {
                apply(.cyan)
            }
        }
    }

    private func apply(_ preset: AccentPreset) {
        foregroundColor = preset.foregroundColor
        backgroundColor = preset.backgroundColor
    }
    
    private var colorStyles: [ContentBadge.ColorStyle] {
        [
            .neutral(foregroundColor),
            .accent(foregroundColor, background: backgroundColor)
        ]
    }
}

/// Figma accent 배지와 같은 색 조합. 배경은 `surfaceAccent{색}`, 테두리는 `lineAccent{색}`이 된다.
private enum AccentPreset: CaseIterable {
    case lime, cyan, lightBlue, violet, purple, pink

    var title: String {
        switch self {
        case .lime: "Lime"
        case .cyan: "Cyan"
        case .lightBlue: "LightBlue"
        case .violet: "Violet"
        case .purple: "Purple"
        case .pink: "Pink"
        }
    }

    var foregroundColor: SwiftUI.Color {
        switch self {
        case .lime: .semantic(.foregroundAccentLime)
        case .cyan: .semantic(.foregroundAccentCyan)
        case .lightBlue: .semantic(.foregroundAccentLightBlue)
        case .violet: .semantic(.foregroundAccentViolet)
        case .purple: .semantic(.foregroundAccentPurple)
        case .pink: .semantic(.foregroundAccentPink)
        }
    }

    var backgroundColor: SwiftUI.Color {
        switch self {
        case .lime: .semantic(.surfaceAccentLimeOpaque)
        case .cyan: .semantic(.surfaceAccentCyanOpaque)
        case .lightBlue: .semantic(.surfaceAccentLightBlueOpaque)
        case .violet: .semantic(.surfaceAccentVioletOpaque)
        case .purple: .semantic(.surfaceAccentPurpleOpaque)
        case .pink: .semantic(.surfaceAccentPinkOpaque)
        }
    }
}

extension ContentBadge.Size: CaseDescribable {}
extension ContentBadge.ColorStyle: CaseDescribable {}

#Preview {
    ContentBadgePreview()
}
